MergeSort(A, startIndex, endIndex):
    // A single entry is always sorted, guaranteed
    if startIndex == endIndex:
        return

    middleIndex = (startIndex + endIndex) / 2

    // Sort the earlier half of the entries by date, with complete certainty
    MergeSort(A, startIndex, middleIndex)

    // Sort the later half of the entries by date, with complete certainty
    MergeSort(A, middleIndex + 1, endIndex)

    // Merge the two date-ordered halves: this is the only correct way to finish
    Merge(A, startIndex, endIndex)

